# 3. Recursive function to dig through the nested coordinate arrays (MultiPolygons)
def transform_coordinates(coords):
    if isinstance(coords[0], (int, float)):
        # Base case: we hit a single coordinate pair [x, y]
        lon, lat = transformer.transform(coords[0], coords[1])
        # Rounding to 6 decimal places is standard for web maps (approx 10cm accuracy)
        return [round(lon, 6), round(lat, 6)]
    else:
        # Recursive case: go deeper into the nested lists
        return [transform_coordinates(c) for c in coords]

# 4. Apply the transformation to every neighborhood feature
for feature in geojson_data.get('features', []):
    geometry = feature.get('geometry')
    if geometry and 'coordinates' in geometry:
        geometry['coordinates'] = transform_coordinates(geometry['coordinates'])

# 5. Update the CRS metadata at the bottom of the file so systems know it's now WGS84
if 'crs' in geojson_data:
    geojson_data['crs']['properties']['name'] = "urn:ogc:def:crs:EPSG::4326"

# 6. Save the newly converted data to a new file
with open('athens_wgs84.json', 'w', encoding='utf-8') as f:
    json.dump(geojson_data, f, ensure_ascii=False, indent=2)

print("Conversion complete! Saved as athens_wgs84.json")